-- Load dbo.MbpLocationSynonym from TSCPRDLIB.MBPLOCSYN export (MBPLOCSYN.20260730.xlsx)
-- Re-runnable full sync (upsert by LocationId; rows absent from the file are deleted).
-- Run in SSMS against the target env's Origination DB AFTER the table migration is applied.
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRAN;
IF OBJECT_ID('tempdb..#stg') IS NOT NULL DROP TABLE #stg;
CREATE TABLE #stg ([LocationId] nvarchar(4000), [Location] nvarchar(4000), [Elevator] nvarchar(4000), [DisplayName] nvarchar(4000), [AddressLine1] nvarchar(4000), [AddressLine2] nvarchar(4000), [City] nvarchar(4000), [State] nvarchar(4000), [Country] nvarchar(4000), [ZipCode] nvarchar(4000), [Phone] nvarchar(4000), [Fax] nvarchar(4000), [Email] nvarchar(4000), [Website] nvarchar(4000), [PushNotificationsHidden] nvarchar(4000), [CashBidsHidden] nvarchar(4000), [Status] nvarchar(4000), [DeletedByUser] nvarchar(4000), [DeletedAtSvStamp] nvarchar(4000), [CreatedByUser] nvarchar(4000), [CreatedStamp] nvarchar(4000), [ChangedByUser] nvarchar(4000), [ChangeStamp] nvarchar(4000));


MERGE dbo.MbpLocationSynonym AS t
USING (SELECT [LocationId], [Location], [Elevator], [DisplayName], [AddressLine1], [AddressLine2], [City], [State], [Country], [ZipCode], [Phone], [Fax], [Email], [Website], [PushNotificationsHidden], [CashBidsHidden], [Status], [DeletedByUser], TRY_CONVERT(datetime2(7), NULLIF([DeletedAtSvStamp],'')) AS [DeletedAtSvStamp], [CreatedByUser], TRY_CONVERT(datetime2(7), NULLIF([CreatedStamp],'')) AS [CreatedStamp], [ChangedByUser], TRY_CONVERT(datetime2(7), NULLIF([ChangeStamp],'')) AS [ChangeStamp] FROM #stg) AS s
ON t.LocationId = s.LocationId
WHEN MATCHED THEN UPDATE SET t.[Location] = s.[Location], t.[Elevator] = s.[Elevator], t.[DisplayName] = s.[DisplayName], t.[AddressLine1] = s.[AddressLine1], t.[AddressLine2] = s.[AddressLine2], t.[City] = s.[City], t.[State] = s.[State], t.[Country] = s.[Country], t.[ZipCode] = s.[ZipCode], t.[Phone] = s.[Phone], t.[Fax] = s.[Fax], t.[Email] = s.[Email], t.[Website] = s.[Website], t.[PushNotificationsHidden] = s.[PushNotificationsHidden], t.[CashBidsHidden] = s.[CashBidsHidden], t.[Status] = s.[Status], t.[DeletedByUser] = s.[DeletedByUser], t.[DeletedAtSvStamp] = s.[DeletedAtSvStamp], t.[CreatedByUser] = s.[CreatedByUser], t.[CreatedStamp] = s.[CreatedStamp], t.[ChangedByUser] = s.[ChangedByUser], t.[ChangeStamp] = s.[ChangeStamp]
WHEN NOT MATCHED BY TARGET THEN INSERT ([LocationId], [Location], [Elevator], [DisplayName], [AddressLine1], [AddressLine2], [City], [State], [Country], [ZipCode], [Phone], [Fax], [Email], [Website], [PushNotificationsHidden], [CashBidsHidden], [Status], [DeletedByUser], [DeletedAtSvStamp], [CreatedByUser], [CreatedStamp], [ChangedByUser], [ChangeStamp]) VALUES (s.[LocationId], s.[Location], s.[Elevator], s.[DisplayName], s.[AddressLine1], s.[AddressLine2], s.[City], s.[State], s.[Country], s.[ZipCode], s.[Phone], s.[Fax], s.[Email], s.[Website], s.[PushNotificationsHidden], s.[CashBidsHidden], s.[Status], s.[DeletedByUser], s.[DeletedAtSvStamp], s.[CreatedByUser], s.[CreatedStamp], s.[ChangedByUser], s.[ChangeStamp])
WHEN NOT MATCHED BY SOURCE THEN DELETE;

DROP TABLE #stg;
COMMIT;
PRINT 'MbpLocationSynonym load complete.';
